#!/usr/bin/env python3
"""
clipboard_monitor.py
Monitors the clipboard every few seconds, stores unique strings found,
and saves the history to a JSON file on exit.
Works on Linux (with xclip/xsel/wl-clipboard), macOS (pbpaste), or Windows.
"""

import time
import sys
import json
from pathlib import Path

try:
    import pyperclip
except ImportError:
    print("pyperclip not found. Install it with: pip install pyperclip")
    sys.exit(1)

POLL_INTERVAL = 3          # seconds between checks
HISTORY_FILE  = Path(__file__).parent / "clipboard_history.json"


def load_history() -> tuple[list[str], list[str]]:
    """Load existing history from disk. Returns (ordered_list, seen_set)."""
    if HISTORY_FILE.exists():
        try:
            data = json.loads(HISTORY_FILE.read_text(encoding="utf-8"))
            entries = data if isinstance(data, list) else []
            print(f"📂 Loaded {len(entries)} existing entr{'y' if len(entries)==1 else 'ies'} from {HISTORY_FILE.name}\n")
            return entries, list(entries)  # list preserves order; set for O(1) lookup
        except (json.JSONDecodeError, OSError):
            print(f"⚠️  Could not read {HISTORY_FILE.name}, starting fresh.\n")
    return [], []


def save_history(history: list[str]) -> None:
    """Persist history list to disk as JSON."""
    try:
        HISTORY_FILE.write_text(
            json.dumps(history, ensure_ascii=False, indent=2),
            encoding="utf-8"
        )
        print(f"\n💾 Saved {len(history)} unique entr{'y' if len(history)==1 else 'ies'} → {HISTORY_FILE}")
    except OSError as e:
        print(f"\n⚠️  Could not save history: {e}")


def monitor_clipboard(interval: int = POLL_INTERVAL):
    history, seen = load_history()
    seen_set: set[str] = set(seen)  # fast membership check

    print(f"📋 Clipboard monitor started (checking every {interval}s). Press Ctrl+C to stop.\n")

    try:
        previous = pyperclip.paste()
    except pyperclip.PyperclipException as e:
        print(f"⚠️  Could not read clipboard: {e}")
        print("    On headless Linux, install xclip or xsel, or run in a desktop environment.")
        sys.exit(1)

    # Capture initial clipboard content if non-empty and not already seen
    if previous and previous not in seen_set:
        history.append(previous)
        seen_set.add(previous)
        print(f"[init] ➕ Stored initial clipboard ({len(previous)} chars). Total unique: {len(history)}\n")
    else:
        print(f"[init] Current clipboard: {repr(previous[:80])}{'…' if len(previous)>80 else ''}\n")

    while True:
        time.sleep(interval)
        try:
            current = pyperclip.paste()
        except pyperclip.PyperclipException as e:
            print(f"⚠️  Clipboard read error: {e}")
            continue

        if current == previous:
            continue  # nothing changed

        timestamp = time.strftime("%H:%M:%S")

        if not current:
            print(f"[{timestamp}] 🗑  Clipboard cleared.\n")
        elif current in seen_set:
            print(f"[{timestamp}] 🔁 Repeated (already stored): {repr(current[:60])}{'…' if len(current)>60 else ''}\n")
        else:
            history.append(current)
            seen_set.add(current)
            preview = repr(current[:60]) + ('…' if len(current) > 60 else '')
            print(f"[{timestamp}] ➕ New unique string #{len(history)}: {preview}\n")

        previous = current


if __name__ == "__main__":
    # Optional: pass interval as first CLI arg, e.g. python3 clipboard_monitor.py 5
    interval = int(sys.argv[1]) if len(sys.argv) > 1 else POLL_INTERVAL
    history_ref: list[str] = []

    # Patch monitor to expose history for the finally block
    import types

    original_monitor = monitor_clipboard

    def _run():
        nonlocal history_ref
        history, seen = load_history()
        seen_set: set[str] = set(seen)

        print(f"📋 Clipboard monitor started (checking every {interval}s). Press Ctrl+C to stop.\n")

        try:
            previous = pyperclip.paste()
        except pyperclip.PyperclipException as e:
            print(f"⚠️  Could not read clipboard: {e}")
            print("    On headless Linux, install xclip or xsel, or run in a desktop environment.")
            sys.exit(1)

        if previous and previous not in seen_set:
            history.append(previous)
            seen_set.add(previous)
            print(f"[init] ➕ Stored initial clipboard ({len(previous)} chars). Total unique: {len(history)}\n")
        else:
            print(f"[init] Current clipboard: {repr(previous[:80])}{'…' if len(previous)>80 else ''}\n")

        history_ref = history  # expose to outer scope

        while True:
            time.sleep(interval)
            try:
                current = pyperclip.paste()
            except pyperclip.PyperclipException as e:
                print(f"⚠️  Clipboard read error: {e}")
                continue

            if current == previous:
                continue

            timestamp = time.strftime("%H:%M:%S")

            if not current:
                print(f"[{timestamp}] 🗑  Clipboard cleared.\n")
            elif current in seen_set:
                print(f"[{timestamp}] 🔁 Repeated (already stored): {repr(current[:60])}{'…' if len(current)>60 else ''}\n")
            else:
                history.append(current)
                seen_set.add(current)
                preview = repr(current[:60]) + ('…' if len(current) > 60 else '')
                print(f"[{timestamp}] ➕ New unique string #{len(history)}: {preview}\n")

            previous = current

    try:
        _run()
    except KeyboardInterrupt:
        print("\n👋 Monitor stopped.")
        save_history(history_ref)
        if history_ref:
            print("\n📋 Unique strings collected this session:")
            for i, entry in enumerate(history_ref, 1):
                print(f"  {i:>3}. {repr(entry[:80])}{'…' if len(entry)>80 else ''}")
